arguments.command:
curl -s -X POST "https://slack.com/api/users.list" -H "Content-Type: application/json" -d '{"token":"***"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
print('ok:', d.get('ok'))
for u in d.get('members',[]):
    flags=[]
    if u.get('is_owner'): flags.append('OWNER')
    if u.get('is_admin'): flags.append('admin')
    if u.get('is_ultra_app'): flags.append('ultra_app')
    print(u['id'], u.get('deleted'), u.get('profile',{}).get('real_name'), u.get('profile',{}).get('title'), flags)
"

